	fn instance_constants(&mut self, sample_rate: i32) {
		self.fSampleRate = sample_rate;
		self.fConst0 = F32::min(1.92e+05, F32::max(1.0, (self.fSampleRate) as F32));
		self.fConst1 = 1.0 / F32::max(1.0, 0.02 * self.fConst0);
		self.fConst2 = F32::max(1.0, 0.001 * self.fConst0);
		self.fConst3 = 1.0 / self.fConst2;
		self.fConst4 = F32::exp(-(1e+02 / self.fConst0));
		self.fConst5 = 1.0 / self.fConst0;
		self.fConst6 = 4.0 / self.fConst0;
		self.fConst7 = 1.0 / F32::tan(1063.7433 / self.fConst0);
		self.fConst8 = 1.0 - self.fConst7;
		self.fConst9 = 1.0 / (self.fConst7 + 1.0);
		self.fConst10 = 3.1415927 / self.fConst0;
		self.fConst11 = 0.0045454544 / self.fConst0;
		self.fConst12 = F32::tan(628.31854 / self.fConst0);
		self.fConst13 = DSP_Drum_faustpower2_f(self.fConst12);
		self.fConst14 = 2.0 * (1.0 - 1.0 / self.fConst13);
		self.fConst15 = 1.0 / self.fConst12;
		self.fConst16 = (self.fConst15 + -1.4142135) / self.fConst12 + 1.0;
		self.fConst17 = (self.fConst15 + 1.4142135) / self.fConst12 + 1.0;
		self.fConst18 = 1.0 / self.fConst17;
		self.iConst19 = (self.fConst0 / F32::min(self.fConst0, 4.8e+04)) as i32;
		self.fConst20 = 1.0 / (self.fConst13 * self.fConst17);
		self.fConst21 = 1.0 / F32::max(1.0, 0.019 * self.fConst0);
	}
	fn instance_init(&mut self, sample_rate: i32) {
		self.instance_constants(sample_rate);
		self.instance_reset_params();
		self.instance_clear();
	}
	fn init(&mut self, sample_rate: i32) {
		DSP_Drum::class_init(sample_rate);
		self.instance_init(sample_rate);
	}
	
